ApexPages.Severity severity = ApexPages.Severity.ERROR;
System.assertEquals(true, severity.equals(ApexPages.Severity.ERROR));
System.assertEquals(false, severity.equals(ApexPages.Severity.WARNING));
System.assertEquals(false, severity.equals(null));
System.assertEquals(severity.hashCode(), ApexPages.Severity.valueOf('ERROR').hashCode());
System.assertNotEquals(severity.hashCode(), ApexPages.Severity.WARNING.hashCode());
System.assertEquals(1, severity.ordinal());
ApexPages.Severity valueOfError = ApexPages.Severity.valueOf('ERROR');
System.assertEquals(ApexPages.Severity.ERROR, valueOfError);
List<ApexPages.Severity> severities = ApexPages.Severity.values();
System.assertEquals(5, severities.size());
System.assertEquals(ApexPages.Severity.FATAL, severities[0]);
System.assertEquals(ApexPages.Severity.ERROR, severities[1]);
System.assertEquals(ApexPages.Severity.WARNING, severities[2]);
System.assertEquals(ApexPages.Severity.INFO, severities[3]);
System.assertEquals(ApexPages.Severity.CONFIRM, severities[4]);

